"""Edge-case tests for coerce-transport -- generated by bug-hunter agent (round 2).

Round 1 found 3 bugs (LazyFrame bypassing Date/Categorical/Duration casts),
confirmed fixed in bd182a8. This round targets:
- RecordBatch date-cast bypass (new bug)
- Arrow CDI boundary with unusual pyarrow types
- Interaction between coerce and the _render_inputs / label_map pipeline
- Unicode / special-character column names through Arrow
- GeoJSON edge cases
- Polars complex types (Struct, List, nested)
- The _to_polars helper used in chart composition
- Timestamp unit coercion edge cases
- Dictionary-encoded Arrow columns
"""

from __future__ import annotations

import json
import math

import numpy as np
import polars as pl
import pyarrow as pa
import pytest

from ferrum._coerce import to_arrow_table


# ================================================================
# Category: RecordBatch date-cast bypass (BUG)
# ================================================================


def test_recordbatch_date32_not_cast_to_timestamp():  # BUG: RecordBatch date32 columns bypass date cast
    """RecordBatch with date32 column: line 120 converts to Table via
    from_batches() and returns immediately, SKIPPING the date32/date64 ->
    timestamp cast at lines 107-118. A pa.Table with date32 gets cast, but
    a RecordBatch with date32 does not.

    Targets line 120: pa.Table.from_batches([data]) returns without date cast.
    """
    schema = pa.schema([("d", pa.date32()), ("y", pa.float64())])
    rb = pa.RecordBatch.from_pydict(
        {"d": pa.array([0, 1, 100], type=pa.date32()), "y": pa.array([1.0, 2.0, 3.0])},
        schema=schema,
    )
    tbl = to_arrow_table(rb)
    d_type = tbl.schema.field("d").type
    assert pa.types.is_timestamp(d_type), (
        f"RecordBatch date32 column was not cast to timestamp: got {d_type}. "
        f"RecordBatch bypasses the date-cast logic at lines 107-118."
    )


def test_recordbatch_date64_not_cast_to_timestamp():  # BUG: RecordBatch date64 columns bypass date cast
    """Same as above but for date64.
    Targets line 120: from_batches bypasses date64 cast.
    """
    schema = pa.schema([("d", pa.date64()), ("y", pa.float64())])
    rb = pa.RecordBatch.from_pydict(
        {
            "d": pa.array([0, 86_400_000, 172_800_000], type=pa.date64()),
            "y": pa.array([1.0, 2.0, 3.0]),
        },
        schema=schema,
    )
    tbl = to_arrow_table(rb)
    d_type = tbl.schema.field("d").type
    assert pa.types.is_timestamp(d_type), (
        f"RecordBatch date64 column was not cast to timestamp: got {d_type}. "
        f"RecordBatch bypasses the date-cast logic at lines 107-118."
    )


def test_recordbatch_date32_renders_without_error():  # BUG: RecordBatch date32 fails downstream render
    """End-to-end: RecordBatch with date32 column should render valid SVG.
    The uncast date32 may cause downstream Rust panics since Rust expects
    timestamp[ms] not date32.
    Targets line 120 -> render pipeline.
    """
    import ferrum as fr

    schema = pa.schema([("d", pa.date32()), ("y", pa.float64())])
    rb = pa.RecordBatch.from_pydict(
        {"d": pa.array([0, 100, 200], type=pa.date32()), "y": pa.array([1.0, 2.0, 3.0])},
        schema=schema,
    )
    svg = fr.Chart(rb).mark_point().encode(x="d", y="y").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


