def test_pyarrow_dictionary_encoded_column():
    """PyArrow table with a dictionary-encoded column. Arrow CDI boundary.
    Tests whether dictionary-encoded (categorical) types survive passthrough.
    Targets line 118: passthrough for non-date table.
    """
    arr = pa.DictionaryArray.from_arrays(
        pa.array([0, 1, 0, 2], type=pa.int8()),
        pa.array(["a", "b", "c"]),
    )
    tbl_in = pa.table({"cat": arr, "y": [1.0, 2.0, 3.0, 4.0]})
    tbl_out = to_arrow_table(tbl_in)
    assert tbl_out is tbl_in
    assert pa.types.is_dictionary(tbl_out.schema.field("cat").type)


def test_pyarrow_dictionary_encoded_renders():  # BUG: Rust rejects dictionary-encoded Arrow arrays
    """Dictionary-encoded pyarrow column used in color encoding.
    Arrow CDI passes dictionary-encoded arrays unchanged (passthrough at line 118),
    but the Rust renderer rejects Dictionary(Int8, Utf8) with
    "unsupported dtype: Dictionary(Int8, Utf8)".
    The coerce layer should either decode dictionary arrays to plain strings,
    or the Rust side should handle them.
    Targets full pipeline with dictionary-encoded input.
    """
    import ferrum as fr

    arr = pa.DictionaryArray.from_arrays(
        pa.array([0, 1, 0], type=pa.int8()),
        pa.array(["cat_a", "cat_b"]),
    )
    tbl = pa.table({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0], "cat": arr})
    svg = fr.Chart(tbl).mark_point().encode(x="x", y="y", color="cat").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


