def test_polars_datetime_with_timezone():
    """Polars Datetime column with timezone.
    Targets line 86: datetime with timezone is NOT Date, so no cast triggered.
    """
    df = pl.DataFrame(
        {
            "dt": pl.Series(
                [1_000_000_000, 2_000_000_000],
                dtype=pl.Datetime("ms", time_zone="UTC"),
            ),
            "y": [1.0, 2.0],
        }
    )
    tbl = to_arrow_table(df)
    assert pa.types.is_timestamp(tbl.schema.field("dt").type)
    assert tbl.schema.field("dt").type.tz == "UTC"


