def test_chart_with_configure_and_special_data_types():
    """Chart with configure_axis() applied and data containing Date columns.
    Tests that the configure pipeline does not interfere with coerce.
    Targets _render_inputs (line 383) -> to_arrow_table with configure.
    """
    import ferrum as fr
    from datetime import date

    df = pl.DataFrame(
        {"d": [date(2024, 1, 1), date(2024, 6, 15), date(2024, 12, 31)], "y": [1.0, 2.0, 3.0]}
    )
    chart = fr.Chart(df).mark_point().encode(x="d", y="y").configure_axis(label_angle=45)
    svg = chart.show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_chart_with_annotations_and_categorical_data():
    """Chart with annotations and categorical data.
    Tests that annotation pipeline doesn't interfere with coerce cast.
    Targets _render_inputs -> to_arrow_table with annotations via + operator.
    """
    import ferrum as fr
    from ferrum.annotation import Annotate
    from ferrum.annotation.primitives import text as ann_text

    df = pl.DataFrame(
        {
            "x": [1.0, 2.0, 3.0],
            "y": [4.0, 5.0, 6.0],
            "cat": pl.Series(["a", "b", "c"], dtype=pl.Categorical),
        }
    )
    chart = fr.Chart(df).mark_point().encode(x="x", y="y", color="cat") + Annotate(
        [ann_text(2.0, 5.0, "label")]
    )
    svg = chart.show_svg()
    assert "<svg" in svg


def test_chart_with_label_map_and_data_coercion():
    """Chart with Axis(label_map=...) applied to data that needs coercion.
    Tests the interaction between label_map remapping (_render.py lines 68-115)
    and the coerce pipeline.
    Targets _render_inputs flow: label_map is applied before to_arrow_table.
    """
    import ferrum as fr
    from ferrum.encoding import X, Y

    df = pl.DataFrame(
        {
            "cat": ["a", "b", "c"],
            "y": [1.0, 2.0, 3.0],
        }
    )
    chart = (
        fr.Chart(df)
        .mark_bar()
        .encode(
            x=X("cat", axis=fr.Axis(label_map={"a": "Alpha", "b": "Beta", "c": "Gamma"})),
            y="y",
        )
    )
    svg = chart.show_svg()
    assert "<svg" in svg


def test_chart_composition_with_different_data_types():
    """Composing charts with different data sources via +.
    Tests _to_polars in the __add__ path with heterogeneous data.
    Targets chart.py __add__ -> _to_polars for null-pad merge.
    """
    import ferrum as fr

    df1 = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    df2 = pl.DataFrame({"x": [1.5, 2.5], "y": [3.5, 5.5]})
    chart1 = fr.Chart(df1).mark_point().encode(x="x", y="y")
    chart2 = fr.Chart(df2).mark_line().encode(x="x", y="y")
    combined = chart1 + chart2
    svg = combined.show_svg()
    assert "<svg" in svg


