def test_geojson_feature_with_numeric_properties():
    """GeoJSON feature with integer and float property values.
    Tests type preservation through _geojson_to_arrow.
    Targets lines 230-245.
    """
    fc = {
        "type": "FeatureCollection",
        "features": [
            {
                "type": "Feature",
                "geometry": {"type": "Point", "coordinates": [0, 0]},
                "properties": {"count": 42, "ratio": 3.14, "name": "test"},
            }
        ],
    }
    tbl = to_arrow_table(fc)
    assert tbl.column("count").to_pylist() == [42]
    assert tbl.column("ratio").to_pylist() == [3.14]
    assert tbl.column("name").to_pylist() == ["test"]


def test_geojson_multipolygon_wrapped():
    """Bare MultiPolygon geometry.
    Targets _is_geojson_geometry_root with MultiPolygon.
    """
    geom = {
        "type": "MultiPolygon",
        "coordinates": [
            [[[0, 0], [1, 0], [1, 1], [0, 0]]],
            [[[2, 2], [3, 2], [3, 3], [2, 2]]],
        ],
    }
    tbl = to_arrow_table(geom)
    assert "__geometry__" in tbl.column_names
    assert tbl.num_rows == 1
    parsed = json.loads(tbl.column("__geometry__")[0].as_py())
    assert parsed["type"] == "MultiPolygon"


