def test_geojson_many_features():
    """GeoJSON with many features to test scaling.
    Targets the full _geojson_to_arrow pipeline with 100 features.
    """
    features = []
    for i in range(100):
        features.append(
            {
                "type": "Feature",
                "geometry": {"type": "Point", "coordinates": [float(i), float(i)]},
                "properties": {"id": i, "name": f"pt_{i}"},
            }
        )
    fc = {"type": "FeatureCollection", "features": features}
    tbl = to_arrow_table(fc)
    assert tbl.num_rows == 100
    assert "__geometry__" in tbl.column_names
    assert "id" in tbl.column_names


def test_geojson_linestring_wrapped():
    """Bare LineString geometry.
    Targets _GEOJSON_GEOMETRY_TYPES and _wrap_geometry_as_feature_collection.
    """
    geom = {"type": "LineString", "coordinates": [[0, 0], [1, 1], [2, 0]]}
