def test_chart_with_configure_grid_and_annotations():
    """Chart using both configure_grid() and annotation via + together with
    data that requires coercion (polars Duration). Tests the full pipeline
    through _resolve_chart_config + to_arrow_table.
    Targets _render_inputs (line 383) with chart_config_dict populated.
    """
    import ferrum as fr
    from ferrum.annotation import Annotate
    from ferrum.annotation.primitives import line as ann_line

    df = pl.DataFrame(
        {
            "dur": pl.Series([1000, 2000, 3000], dtype=pl.Duration("ns")),
            "y": [1.0, 2.0, 3.0],
        }
    )
    chart = fr.Chart(df).mark_point().encode(x="dur", y="y").configure_grid(
        x=True, y=True, color="#ddd"
    ) + Annotate([ann_line(0, 0, 3000, 3.0)])
    svg = chart.show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


